Task: Your adventurer needs magical amulets to boost their stats! Implement the `calculateBonus` method in the base `Amulet` class and its subclasses to demonstrate polymorphism. Ensure robust input validation for the `baseValue` in `calculateBonus`.

Submitted code:
```
class Amulet {
  constructor(name) {
    this.name = name;
  }

  calculateBonus(baseValue) {
    // 1. Input validation: baseValue must be a number and >= 0
    if (typeof baseValue !== 'number' || baseValue < 0) {
      return 0;
    }

    // 2. Default return for the base class (to be overridden)
    return 0;
  }
}

class StrengthAmulet extends Amulet {
  constructor(name, strengthModifier) {
    super(name);
    this.strengthModifier = strengthModifier;
  }

  calculateBonus(baseValue) {
    // 3. Validation from parent, then custom logic
    if (super.calculateBonus(baseValue) === 0 && baseValue !== 0) return 0;

    // Multiplicative bonus
    return baseValue * this.strengthModifier;
  }
}

class WisdomAmulet extends Amulet {
  constructor(name, wisdomFactor) {
    super(name);
    this.wisdomFactor = wisdomFactor;
  }

  calculateBonus(baseValue) {
    // 3. Validation from parent, then custom logic
    if (super.calculateBonus(baseValue) === 0 && baseValue !== 0) return 0;

    // Additive bonus
    return baseValue + this.wisdomFactor;
  }
}

